-- Dedicated Snowflake access for Hightouch reverse ETL and Fivetran ingestion.
-- Replace the two RSA placeholders with the headerless Base64 public keys generated by
-- scripts/generate_service_keys.ps1. Never place private keys in this file or Git.

USE ROLE ACCOUNTADMIN;

-- Hightouch: read governed analytics and own its Lightning-engine working schemas.
CREATE ROLE IF NOT EXISTS HIGHTOUCH_ROLE;
GRANT USAGE ON WAREHOUSE CAREMATCH_INGEST_WH TO ROLE HIGHTOUCH_ROLE;
GRANT USAGE ON DATABASE CAREMATCH TO ROLE HIGHTOUCH_ROLE;
GRANT USAGE ON SCHEMA CAREMATCH.ANALYTICS TO ROLE HIGHTOUCH_ROLE;
GRANT SELECT ON ALL TABLES IN SCHEMA CAREMATCH.ANALYTICS TO ROLE HIGHTOUCH_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA CAREMATCH.ANALYTICS TO ROLE HIGHTOUCH_ROLE;
GRANT SELECT ON ALL VIEWS IN SCHEMA CAREMATCH.ANALYTICS TO ROLE HIGHTOUCH_ROLE;
GRANT SELECT ON FUTURE VIEWS IN SCHEMA CAREMATCH.ANALYTICS TO ROLE HIGHTOUCH_ROLE;

CREATE SCHEMA IF NOT EXISTS CAREMATCH.HIGHTOUCH_AUDIT;
CREATE SCHEMA IF NOT EXISTS CAREMATCH.HIGHTOUCH_PLANNER;
GRANT OWNERSHIP ON SCHEMA CAREMATCH.HIGHTOUCH_AUDIT TO ROLE HIGHTOUCH_ROLE COPY CURRENT GRANTS;
GRANT OWNERSHIP ON SCHEMA CAREMATCH.HIGHTOUCH_PLANNER TO ROLE HIGHTOUCH_ROLE COPY CURRENT GRANTS;

CREATE USER IF NOT EXISTS HIGHTOUCH_USER TYPE = SERVICE;
ALTER USER HIGHTOUCH_USER SET
  RSA_PUBLIC_KEY = '<HIGHTOUCH_RSA_PUBLIC_KEY>'
  DEFAULT_ROLE = HIGHTOUCH_ROLE
  DEFAULT_WAREHOUSE = CAREMATCH_INGEST_WH
  DEFAULT_NAMESPACE = 'CAREMATCH.ANALYTICS';
GRANT ROLE HIGHTOUCH_ROLE TO USER HIGHTOUCH_USER;

-- Fivetran: dedicated landing database and compute for managed SaaS ingestion.
CREATE ROLE IF NOT EXISTS FIVETRAN_ROLE;
CREATE WAREHOUSE IF NOT EXISTS FIVETRAN_WAREHOUSE
  WAREHOUSE_SIZE = 'XSMALL'
  AUTO_SUSPEND = 60
  AUTO_RESUME = TRUE
  INITIALLY_SUSPENDED = TRUE;
CREATE DATABASE IF NOT EXISTS FIVETRAN_LANDING;

GRANT USAGE ON WAREHOUSE FIVETRAN_WAREHOUSE TO ROLE FIVETRAN_ROLE;
GRANT USAGE, MONITOR, CREATE SCHEMA ON DATABASE FIVETRAN_LANDING TO ROLE FIVETRAN_ROLE;

CREATE USER IF NOT EXISTS FIVETRAN_USER TYPE = SERVICE;
ALTER USER FIVETRAN_USER SET
  RSA_PUBLIC_KEY = '<FIVETRAN_RSA_PUBLIC_KEY>'
  DEFAULT_ROLE = FIVETRAN_ROLE
  DEFAULT_WAREHOUSE = FIVETRAN_WAREHOUSE
  DEFAULT_NAMESPACE = 'FIVETRAN_LANDING.PUBLIC';
ALTER USER FIVETRAN_USER SET BINARY_INPUT_FORMAT = 'BASE64';
ALTER USER FIVETRAN_USER SET TIMESTAMP_INPUT_FORMAT = 'AUTO';
GRANT ROLE FIVETRAN_ROLE TO USER FIVETRAN_USER;

SHOW USERS LIKE '%TOUCH_USER';
SHOW USERS LIKE 'FIVETRAN_USER';
SHOW GRANTS TO ROLE HIGHTOUCH_ROLE;
SHOW GRANTS TO ROLE FIVETRAN_ROLE;
